  'This browser doesn\'t support passkeys, and this instance requires an account. Try a browser or device with passkey support.': 'Αυτό το πρόγραμμα περιήγησης δεν υποστηρίζει κλειδιά πρόσβασης και αυτή η εγκατάσταση απαιτεί λογαριασμό. Δοκίμασε ένα πρόγραμμα περιήγησης ή μια συσκευή με υποστήριξη κλειδιών πρόσβασης.',
