  'This browser doesn\'t support passkeys. Sign in with your name and password instead.': 'Αυτό το πρόγραμμα περιήγησης δεν υποστηρίζει κλειδιά πρόσβασης. Συνδέσου με το όνομα και τον κωδικό σου.',
