  'Set · sign in as “{0}”': 'Ορίστηκε · σύνδεση ως «{0}»',
  'Not set. Handy for signing in where passkeys don’t work.': 'Δεν έχει οριστεί. Βολεύει για σύνδεση εκεί που τα κλειδιά πρόσβασης δεν δουλεύουν.',
  'Set a password': 'Όρισε έναν κωδικό',
  'Change password': 'Αλλαγή κωδικού',
  'Sign in as “{0}” with it on devices where passkeys do not work. Saving signs you out everywhere else, and paired phones have to be paired again.': 'Συνδέσου ως «{0}» με αυτόν σε συσκευές όπου τα κλειδιά πρόσβασης δεν δουλεύουν. Η αποθήκευση σε αποσυνδέει από παντού αλλού και τα συνδεδεμένα κινητά πρέπει να ζευγαρωθούν ξανά.',
  'Confirm with passkey & save': 'Επιβεβαίωση με κλειδί πρόσβασης και αποθήκευση',
