  'Password saved. You’re now signed out everywhere else.': 'Ο κωδικός αποθηκεύτηκε. Τώρα έχεις αποσυνδεθεί από παντού αλλού.',
  'Remove password': 'Αφαίρεση κωδικού',
  'Remove your password?': 'Να αφαιρεθεί ο κωδικός σου;',
