  'Enter your name or e-mail.': 'Γράψε το όνομα ή το e-mail σου.',
  'E-mail (optional)': 'E-mail (προαιρετικό)',
  'Lets you sign in with it instead of your name. Nothing is ever sent to it.': 'Σου επιτρέπει να συνδέεσαι με αυτό αντί για το όνομά σου. Δεν στέλνεται ποτέ τίποτα σε αυτό.',
  'That is not an e-mail address.': 'Αυτό δεν είναι διεύθυνση e-mail.',
  'Another profile already uses this e-mail address.': 'Άλλο προφίλ χρησιμοποιεί ήδη αυτή τη διεύθυνση e-mail.',
  'Sign-in e-mail': 'E-mail σύνδεσης',
  'Sign in with “{0}” instead of your name': 'Σύνδεση με «{0}» αντί για το όνομά σου',
