  'E-mail removed': 'Το e-mail αφαιρέθηκε',
  'Too many attempts. Try again {0}.': 'Πάρα πολλές προσπάθειες. Δοκίμασε ξανά {0}.',
  'Use at least {0} characters.': 'Χρησιμοποίησε τουλάχιστον {0} χαρακτήρες.',
  'That password is too long.': 'Αυτός ο κωδικός είναι πολύ μεγάλος.',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': 'Αυτός ο κωδικός μαντεύεται πολύ εύκολα. Δοκίμασε έναν μεγαλύτερο ή μερικές τυχαίες λέξεις μαζί.',
  'Another profile already signs in with this name.': 'Άλλο προφίλ συνδέεται ήδη με αυτό το όνομα.',
  'That invite code is not valid.': 'Αυτός ο κωδικός πρόσκλησης δεν είναι έγκυρος.',
  'Your current password is not right.': 'Ο τρέχων κωδικός σου δεν είναι σωστός.',
  'Your passkey could not be confirmed.': 'Το κλειδί πρόσβασής σου δεν μπόρεσε να επιβεβαιωθεί.',
  'This password is the only way into your profile, so it cannot be removed.': 'Αυτός ο κωδικός είναι ο μόνος τρόπος εισόδου στο προφίλ σου, γι\' αυτό δεν μπορεί να αφαιρεθεί.',
  'That reset code is wrong or has expired. Ask your admin for a new one.': 'Αυτός ο κωδικός επαναφοράς είναι λάθος ή έχει λήξει. Ζήτα νέο από τον διαχειριστή σου.',
