  'Sign out?': 'Αποσύνδεση;',
  'Sign out': 'Αποσύνδεση',
  'Sign out everywhere?': 'Αποσύνδεση από παντού;',
  'You have a workout running. It waits on this device until you’re back on this account.': 'Έχεις μια προπόνηση σε εξέλιξη. Περιμένει σε αυτή τη συσκευή μέχρι να γυρίσεις σε αυτόν τον λογαριασμό.',
  'Sign out everywhere': 'Αποσύνδεση από παντού',
