  'Ends this profile’s sessions on all your devices.': 'Τερματίζει τις συνεδρίες αυτού του προφίλ σε όλες τις συσκευές σου.',
  'Signed out on all devices': 'Αποσυνδέθηκες από όλες τις συσκευές',
