  'Music playing on this phone stops during a workout and does not resume by itself.': 'Η μουσική που παίζει σε αυτό το κινητό σταματά κατά τη διάρκεια μιας προπόνησης και δεν συνεχίζει μόνη της.',
  'The end of a rest rings through silent. Music turns down for it and keeps playing.': 'Το τέλος ενός διαλείμματος ηχεί ακόμα και στο αθόρυβο. Η μουσική χαμηλώνει και συνεχίζει να παίζει.',
  'The quieter three-beep sound from before 1.3.9, instead of the louder chime.': 'Ο πιο ήσυχος ήχος τριών μπιπ από πριν την 1.3.9, αντί για το πιο δυνατό κουδούνισμα.',
