  'Auto-backup on changes': 'Αυτόματο αντίγραφο ασφαλείας στις αλλαγές',
  'Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.': 'Αποθηκεύει ένα αντίγραφο με ημερομηνία στο Documents/openGym μετά το τέλος μιας προπόνησης ή την επεξεργασία μιας ρουτίνας και κρατά τα {0} πιο πρόσφατα. Δείξε μια εφαρμογή συγχρονισμού σε αυτόν τον φάκελο ή αντίγραψέ το με το χέρι.',
  'Reset everything?': 'Να γίνει επαναφορά των πάντων;',
  'Reset everything': 'Επαναφορά των πάντων',
  'Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.': 'Διαγράφει το πλάνο σου, τις προπονήσεις, το σωματικό βάρος, τις φωτογραφίες και τα βίντεο σε αυτή τη συσκευή. Δεν μπορεί να αναιρεθεί.',
  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Διαγράφει το πλάνο σου, τις προπονήσεις, το σωματικό βάρος, τις φωτογραφίες και τα βίντεο από το προφίλ σου σε αυτόν τον διακομιστή και σε κάθε συνδεδεμένη συσκευή. Δεν μπορεί να αναιρεθεί.',
  'Sync failed: the server refused the upload as too large. Your changes have not reached the server.': 'Ο συγχρονισμός απέτυχε: ο διακομιστής απέρριψε τη μεταφόρτωση επειδή ήταν πολύ μεγάλη. Οι αλλαγές σου δεν έφτασαν στον διακομιστή.',
  'This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.': 'Αυτή η συσκευή έχει γεμίσει χώρο αποθήκευσης: η αλλαγή δεν αποθηκεύεται σε αυτήν. Αν είσαι συνδεδεμένος, πηγαίνει παρ\' όλα αυτά στον διακομιστή.',
