  'Follow the routine ({0})': 'Ακολούθησε τη ρουτίνα ({0})',
  'Applies to every exercise in this routine that does not set its own rule.': 'Ισχύει για κάθε άσκηση αυτής της ρουτίνας που δεν ορίζει δικό της κανόνα.',
