  'Coach': 'Προπονητής',
  'Ask for a review': 'Ζήτα αξιολόγηση',
  '{0} of {1} Coach runs used today': '{0} από {1} εκτελέσεις του προπονητή χρησιμοποιήθηκαν σήμερα',
  'Controls': 'Έλεγχοι',
  'Undo the last Coach changes': 'Αναίρεση των τελευταίων αλλαγών του προπονητή',
  '{0} days a week': { one: '{0} ημέρα την εβδομάδα', other: '{0} ημέρες την εβδομάδα' },
  '{0} min': '{0} λ',
  '{0}h {1}m': '{0}ω {1}λ',
  'The Coach is on': 'Ο προπονητής είναι ενεργός',
  'the configured AI provider': 'ο ρυθμισμένος πάροχος AI',
  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Το όνομά σου, τα στοιχεία σύνδεσής σου και όλα τα άλλα για τον λογαριασμό σου μένουν εδώ. Δεδομένα άλλων ανθρώπων δεν περιλαμβάνονται ποτέ.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Ο προπονητής δεν είναι γιατρός ή φυσιοθεραπευτής. Αν κάτι πονάει, ρώτα έναν επαγγελματία.',
  'Not now': 'Όχι τώρα',
  'Meet the Coach': 'Γνώρισε τον προπονητή',
  'Review': 'Αξιολόγηση',
  'Automatic reviews': 'Αυτόματες αξιολογήσεις',
  'Off. The Coach only looks when you ask.': 'Ανενεργές. Ο προπονητής κοιτάζει μόνο όταν ζητήσεις.',
  'You are only notified when the Coach actually has something to suggest.': 'Ειδοποιείσαι μόνο όταν ο προπονητής έχει πραγματικά κάτι να προτείνει.',
  'On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.': 'Σε αυτό το κινητό ο προπονητής μπορεί να κοιτάξει μόνο όσο η εφαρμογή είναι ανοιχτή: αμέσως μετά από μια προπόνηση ή την επόμενη φορά που θα την ανοίξεις.',
  'When': 'Πότε',
