  'As soon as you have logged enough': 'Μόλις έχεις καταγράψει αρκετά',
  'Day': 'Ημέρα',
  'After how many workouts': 'Μετά από πόσες προπονήσεις',
  'applied': 'εφαρμόστηκε',
  'declined': 'απορρίφθηκε',
  'Your plan': 'Το πλάνο σου',
  'What are you training for?': 'Για τι προπονείσαι;',
  'Where are you starting from?': 'Από πού ξεκινάς;',
  'How many days a week?': 'Πόσες ημέρες την εβδομάδα;',
  'Which days suit you? (optional)': 'Ποιες ημέρες σε βολεύουν; (προαιρετικό)',
  'How long is a session?': 'Πόσο διαρκεί μια προπόνηση;',
  'min': 'λεπτά',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Ο προπονητής προσαρμόζει τον όγκο στον χρόνο που έχεις πραγματικά, μαζί με το διάλειμμα ανάμεσα στα σετ.',
  'What can you train with?': 'Με τι μπορείς να προπονηθείς;',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Διάλεξε ό,τι έχεις διαθέσιμο. Άφησέ το κενό και ο προπονητής θα χρησιμοποιήσει όλη τη βιβλιοθήκη.',
  'Anything to work around?': 'Κάτι που πρέπει να προσέξεις;',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Τραυματισμοί, αρθρώσεις που διαμαρτύρονται, κινήσεις που δεν μπορείς να κάνεις, ή πρακτικοί περιορισμοί όπως προπόνηση στις 6 το πρωί σε διαμέρισμα.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'π.χ. «ενοχλεί ο αριστερός ώμος, όχι πιέσεις ώμων με μπάρα»',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Αν κάτι πονάει πραγματικά, δες έναν επαγγελματία. Ο προπονητής θα προγραμματίσει συντηρητικά, αλλά δεν μπορεί να διαγνώσει τίποτα.',
  'Anything else?': 'Κάτι άλλο;',
  'Exercises you love': 'Ασκήσεις που αγαπάς',
  'e.g. “deadlifts, anything with a kettlebell”': 'π.χ. «άρσεις θανάτου, οτιδήποτε με kettlebell»',
  'Exercises you would rather not': 'Ασκήσεις που προτιμάς να αποφύγεις',
  'e.g. “I hate lunges”': 'π.χ. «μισώ τις προβολές»',
  'Anything you want the Coach to know': 'Ό,τι θέλεις να ξέρει ο προπονητής',
  'e.g. “I want visible arms progress by spring”': 'π.χ. «θέλω ορατή πρόοδο στα μπράτσα μέχρι την άνοιξη»',
  'Build my plan': 'Φτιάξε το πλάνο μου',
  'Your plan is live': 'Το πλάνο σου είναι ενεργό',
  'That proposal can’t be read.': 'Αυτή η πρόταση δεν μπορεί να διαβαστεί.',
  'Discard this plan?': 'Να απορριφθεί αυτό το πλάνο;',
  'Nothing is saved, and you can ask again anytime.': 'Δεν αποθηκεύεται τίποτα, και μπορείς να ρωτήσεις ξανά όποτε θέλεις.',
  'Revision {0}': 'Αναθεώρηση {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'Αντικαθιστά την τρέχουσα εβδομάδα σου. Οι ημέρες που αυτό το πλάνο αφήνει κενές γίνονται ημέρες ξεκούρασης.',
  'Could not apply those changes': 'Δεν ήταν δυνατή η εφαρμογή αυτών των αλλαγών',
  'Dismiss these suggestions?': 'Να απορριφθούν αυτές οι προτάσεις;',
  'Nothing changes, and the Coach will remember you turned these down.': 'Δεν αλλάζει τίποτα, και ο προπονητής θα θυμάται ότι τις απέρριψες.',
  'Dismiss': 'Απόρριψη',
  'Based on your last {0} sessions': 'Με βάση τις τελευταίες {0} προπονήσεις σου',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Το πλάνο σου άλλαξε αφότου το κοίταξε ο προπονητής. Οι προτάσεις που δεν ταιριάζουν πια είναι γκριζαρισμένες. Ζήτα νέα αξιολόγηση για να τις δεις ξανά.',
  'Doesn’t match your plan any more, so it can’t be applied.': 'Δεν ταιριάζει πια με το πλάνο σου, οπότε δεν μπορεί να εφαρμοστεί.',
