  'Name it after where you train (like "Home" or "Gym"), then tick what you’ve got there.': 'Δώσε του το όνομα του χώρου όπου προπονείσαι (π.χ. «Σπίτι» ή «Γυμναστήριο») και μετά τσέκαρε ό,τι έχεις εκεί.',
  'Profile name': 'Όνομα προφίλ',
  'Body-weight exercises are always available, unless they need a pull-up bar or a bench.': 'Οι ασκήσεις με το βάρος του σώματος είναι πάντα διαθέσιμες, εκτός αν χρειάζονται μονόζυγο ή πάγκο.',
