  'Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.': 'Φιλτράρει τη βιβλιοθήκη ασκήσεων και τον επιλογέα, και επισημαίνει ασκήσεις ρουτίνας που χρειάζονται κάτι που δεν έχεις στο ενεργό προφίλ.',
