  'Disconnect from your server?': 'Αποσύνδεση από τον διακομιστή σου;',
  'Disconnected. Back to local-only': 'Αποσυνδέθηκες. Πίσω σε μόνο τοπική χρήση',
  'Connect to my server': 'Σύνδεση με τον διακομιστή μου',
  'Sync this device to your own self-hosted openGym instead.': 'Συγχρόνισε αυτή τη συσκευή με τη δική σου self-hosted εγκατάσταση openGym.',
  'Pair the mobile app': 'Σύζευξη της εφαρμογής κινητού',
