  'On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'Στην εφαρμογή openGym, διάλεξε «Σύνδεση με τον διακομιστή μου» και μετά βάλε αυτή τη διεύθυνση και τον παρακάτω κωδικό. Λήγει σε 5 λεπτά.',
