  'Replaces the sessions in your rotation and starts it over with the first one.': 'Αντικαθιστά τις προπονήσεις στην εναλλαγή σου και την ξεκινά από την αρχή με την πρώτη.',
  'Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.': 'Έγινε εισαγωγή! {0} ρουτίνες είναι στο πλάνο σου και η εναλλαγή σου ξεκινά από την αρχή με αυτές. Τα λέμε στην επόμενη προπόνηση.',
