  'Nothing yet. Every plan, suggestion and debrief will be kept here, whether you said yes or no.': 'Τίποτα ακόμα. Κάθε πλάνο, πρόταση και ανάλυση θα αποθηκεύεται εδώ, είτε είπες ναι είτε όχι.',
