  'Not enough people are sharing yet ({0} of {1} needed). Rope in your gym mates!': 'Δεν μοιράζονται ακόμα αρκετά άτομα ({0} από {1} που χρειάζονται). Φώναξε τους φίλους σου από το γυμναστήριο!',
