  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Κορυφαία σετ καταγράφηκαν χωρίς βαθμολογία προσπάθειας· πρόσθεσε RIR για να καταλαβαίνει η επόμενη ανασκόπηση πόσο δύσκολα ήταν.',
