  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'Έγινε το μεγαλύτερο μέρος της δουλειάς. Ένα δυο σετ έμειναν πίσω, κάτι που είναι εντάξει μία φορά. Γίνεται σήμα μόνο αν αποτύχουν τα ίδια σετ και την επόμενη φορά.',
