  'Forgot to finish on time? Set how long the session really took. It keeps its start time and its sets.': 'Ξέχασες να τελειώσεις εγκαίρως; Όρισε πόση ώρα κράτησε πραγματικά η προπόνηση. Κρατάει την ώρα έναρξης και τα σετ της.',
  'The session keeps its length. Personal records are worked out again from the new order.': 'Η προπόνηση κρατάει τη διάρκειά της. Τα προσωπικά ρεκόρ υπολογίζονται ξανά από τη νέα σειρά.',
