  'Pairs of each size you own. Every set row loads from this list, so a home gym with one pair of 45s is never told to use two.': 'Ζευγάρια από κάθε μέγεθος που έχεις. Κάθε γραμμή σετ φορτώνει από αυτή τη λίστα, οπότε σε ένα σπιτικό γυμναστήριο με ένα ζευγάρι 45άρια δεν θα σου πει ποτέ να βάλεις δύο.',
