  'Get the Android app': 'Πάρε την εφαρμογή για Android',
  'Download the APK from opengym.ch': 'Κατέβασε το APK από το opengym.ch',
  'Releases are checked on GitHub. The download is verified against its checksum before the installer opens.': 'Οι εκδόσεις ελέγχονται στο GitHub. Η λήψη επαληθεύεται με το checksum της πριν ανοίξει το πρόγραμμα εγκατάστασης.',
  'The web app updates together with your server. The Android app installs its own updates from here.': 'Η διαδικτυακή εφαρμογή ενημερώνεται μαζί με τον διακομιστή σου. Η εφαρμογή Android εγκαθιστά τις δικές της ενημερώσεις από εδώ.',
