  'Add this device\'s workouts to your profile?': 'Να προστεθούν οι προπονήσεις αυτής της συσκευής στο προφίλ σου;',
  '{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Καταγράφηκαν {0} προπονήσεις και {1} ζυγίσεις σε αυτή τη συσκευή ενώ ήσουν χωρίς σύνδεση. Πρόσθεσέ τες στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Καταγράφηκε {0} προπόνηση και {1} ζύγιση σε αυτή τη συσκευή ενώ ήσουν χωρίς σύνδεση. Πρόσθεσέ τες στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
  '{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Καταγράφηκε {0} προπόνηση και {1} ζυγίσεις σε αυτή τη συσκευή ενώ ήσουν χωρίς σύνδεση. Πρόσθεσέ τες στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
  '{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Καταγράφηκαν {0} προπονήσεις και {1} ζύγιση σε αυτή τη συσκευή ενώ ήσουν χωρίς σύνδεση. Πρόσθεσέ τες στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
  'Add them': 'Πρόσθεσέ τες',
  'Keep profile as is': 'Κράτα το προφίλ όπως είναι',
  'Offline. Your changes are saved on this device and sync when you’re back online.': 'Εκτός σύνδεσης. Οι αλλαγές σου αποθηκεύονται σε αυτή τη συσκευή και συγχρονίζονται όταν επανέλθεις στο διαδίκτυο.',
  'Offline. Showing the last copy synced with the server.': 'Εκτός σύνδεσης. Εμφανίζεται το τελευταίο αντίγραφο που συγχρονίστηκε με τον διακομιστή.',
  'Not synced yet. Tap to retry.': 'Δεν έχει συγχρονιστεί ακόμα. Πάτα για να δοκιμάσεις ξανά.',
  'Back online and synced with the server.': 'Επανήλθες στο διαδίκτυο και συγχρονίστηκες με τον διακομιστή.',
