  'The server cannot be reached': 'Δεν είναι δυνατή η σύνδεση με τον διακομιστή',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'Δεν είναι δυνατή η σύνδεση με τον διακομιστή σου. Οι αλλαγές σου αποθηκεύονται σε αυτή τη συσκευή και συγχρονίζονται μόλις απαντήσει ξανά.',
  'Your server can’t be reached. Showing the last copy synced with it.': 'Δεν είναι δυνατή η σύνδεση με τον διακομιστή σου. Εμφανίζεται το τελευταίο αντίγραφο που συγχρονίστηκε μαζί του.',
  'Server address unknown': 'Άγνωστη διεύθυνση διακομιστή',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Κάνε ξανά σύζευξη ή κάνε πρώτα εξαγωγή αντιγράφου ασφαλείας. Αν συνεχίσεις ούτως ή άλλως, ένα αντίγραφο αυτών των αλλαγών μένει σε αυτή τη συσκευή μέχρι να συνδεθεί ξανά με αυτόν τον διακομιστή με αυτόν τον λογαριασμό. Τότε προστίθενται πάλι.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Συνδέσου ξανά ή κάνε πρώτα εξαγωγή αντιγράφου ασφαλείας. Αν συνεχίσεις ούτως ή άλλως, ένα αντίγραφο αυτών των αλλαγών μένει σε αυτή τη συσκευή μέχρι να συνδεθεί ξανά με αυτόν τον διακομιστή με αυτόν τον λογαριασμό. Τότε προστίθενται πάλι.',
  '{0} set · {1} work': '{0} σετ · {1} δουλειά',
  'Every exercise in this workout': 'Κάθε άσκηση σε αυτή την προπόνηση',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': 'Δεν έχουν μείνει σετ σε αυτή την προπόνηση, οπότε δεν υπάρχει τίποτα να αποθηκευτεί. Να διαγραφεί από το ιστορικό σου;',
  'Photo, GIF or video': 'Φωτογραφία, GIF ή βίντεο',
  'Optional. A picture makes it easier to spot in a list.': 'Προαιρετικό. Μια εικόνα την κάνει πιο εύκολη να ξεχωρίσει σε μια λίστα.',
  'Add': 'Προσθήκη',
  'Change': 'Αλλαγή',
  'Video or guide link (optional)': 'Σύνδεσμος βίντεο ή οδηγού (προαιρετικό)',
