  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': 'Αυτός ο τύπος αρχείου δεν υποστηρίζεται. Χρησιμοποίησε φωτογραφία, GIF ή βίντεο MP4, MOV ή WebM.',
  'That file is too big. Max {0} MB.': 'Αυτό το αρχείο είναι πολύ μεγάλο. Μέγιστο {0} MB.',
