  'That photo is too large to process on this device.': 'Αυτή η φωτογραφία είναι πολύ μεγάλη για να επεξεργαστεί σε αυτή τη συσκευή.',
  'You’re offline. Try again once you’re back online.': 'Είσαι εκτός σύνδεσης. Δοκίμασε ξανά όταν επανέλθεις στο διαδίκτυο.',
