  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'Αυτό το βίντεο μπορεί να μην παίζει σε κάθε συσκευή. Το MP4 (H.264) παίζει παντού.',
  'Your photo and video space on the server is full ({0} of {1} MB).': 'Ο χώρος για φωτογραφίες και βίντεο στον διακομιστή σου είναι γεμάτος ({0} από {1} MB).',
  'The server refused the file as too large.': 'Ο διακομιστής απέρριψε το αρχείο επειδή είναι πολύ μεγάλο.',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'Μένει μόνο σε αυτή τη συσκευή. Η εξαγωγή με φωτογραφίες και βίντεο κρατά αντίγραφο.',
  'Your server does not store photos and videos yet.': 'Ο διακομιστής σου δεν αποθηκεύει ακόμα φωτογραφίες και βίντεο.',
