  'The server has 1 workout that is not in this backup, logged since it was made or on another device. Replacing deletes it.': 'Ο διακομιστής έχει 1 προπόνηση που δεν υπάρχει σε αυτό το αντίγραφο ασφαλείας, καταγράφηκε μετά τη δημιουργία του ή σε άλλη συσκευή. Η αντικατάσταση τη διαγράφει.',
  'The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.': 'Ο διακομιστής έχει {0} προπονήσεις που δεν υπάρχουν σε αυτό το αντίγραφο ασφαλείας, καταγράφηκαν μετά τη δημιουργία του ή σε άλλη συσκευή. Η αντικατάσταση τις διαγράφει.',
  'Replace anyway': 'Αντικατάσταση παρόλα αυτά',
