  'The Coach took too long and gave up.': 'Ο Προπονητής άργησε πολύ και τα παράτησε.',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'Ο Προπονητής δεν μπόρεσε να συνδεθεί στον πάροχό του. Ο ιδιοκτήτης της εγκατάστασης πρέπει να ελέγξει τις ρυθμίσεις.',
  'The Coach isn’t installed properly on this instance.': 'Ο Προπονητής δεν είναι εγκατεστημένος σωστά σε αυτή την εγκατάσταση.',
