  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'Ο πάροχος AI απέρριψε το κλειδί σε αυτό το τηλέφωνο. Έλεγξέ το στις Ρυθμίσεις → AI Προπονητής.',
  'The Coach isn’t set up on this phone. Check Settings → AI Coach.': 'Ο Προπονητής δεν έχει ρυθμιστεί σε αυτό το τηλέφωνο. Έλεγξε τις Ρυθμίσεις → AI Προπονητής.',
