  'Add to the rotation': 'Πρόσθεσε στην εναλλαγή',
  'No rotation yet. Add routines in the order you want to train them. The first one you haven’t logged stays up next.': 'Δεν υπάρχει εναλλαγή ακόμη. Πρόσθεσε ρουτίνες με τη σειρά που θέλεις να τις προπονηθείς. Η πρώτη που δεν έχεις καταχωρίσει μένει επόμενη.',
  'Use this rotation': 'Χρήση αυτής της εναλλαγής',
  'Use this rotation?': 'Να χρησιμοποιηθεί αυτή η εναλλαγή;',
  'Your own loop gets replaced.': 'Ο δικός σου κύκλος αντικαθίσταται.',
  'Your coach gives up control of this week: openGym owns the queue from here on and repeats these sessions by itself once they are all done. A new week from the coach’s app would replace this rotation.': 'Ο προπονητής σου παραδίδει τον έλεγχο αυτής της εβδομάδας: από εδώ και πέρα το openGym κρατά τη σειρά και επαναλαμβάνει μόνο του αυτές τις προπονήσεις μόλις ολοκληρωθούν όλες. Μια νέα εβδομάδα από την εφαρμογή του προπονητή θα αντικαταστήσει αυτή την εναλλαγή.',
  'Start new pass': 'Ξεκίνα νέο πέρασμα',
  'This rotation couldn’t be read. Another device may have written it.': 'Αυτή η εναλλαγή δεν μπόρεσε να διαβαστεί. Μπορεί να την έγραψε άλλη συσκευή.',
  'Discard it': 'Απόρριψή της',
