  '{0} set becomes {1}: one on each side, {2}s held every time.': 'Το {0} σετ γίνεται {1}: ένα σε κάθε πλευρά, με κράτημα {2} δευτ. κάθε φορά.',
  '{0} sets become {1}: one on each side, {2}s held every time.': { one: 'Το {0} σετ γίνεται {1}: ένα σε κάθε πλευρά, με κράτημα {2} δευτ. κάθε φορά.', other: 'Τα {0} σετ γίνονται {1}: ένα σε κάθε πλευρά, με κράτημα {2} δευτ. κάθε φορά.' },
  'For side planks, single-arm holds and the like. Trains each side on its own.': 'Για πλάγιες σανίδες, κρατήματα με το ένα χέρι και παρόμοια. Προπονεί κάθε πλευρά ξεχωριστά.',
  'Compare photos': 'Σύγκριση φωτογραφιών',
  'Photo': 'Φωτογραφία',
