  'Scroll to 0:00 to turn the rest timer off.': 'Κύλισε στο 0:00 για να απενεργοποιήσεις το χρονόμετρο διαλείμματος.',
  'The short break between the bursts of a rest-pause set.': 'Το σύντομο διάλειμμα ανάμεσα στις εκρήξεις ενός σετ rest-pause.',
  'Each exercise can have its own rest too. Set it in the exercise settings of a routine.': 'Κάθε άσκηση μπορεί να έχει και δικό της διάλειμμα. Όρισέ το στις ρυθμίσεις άσκησης μιας ρουτίνας.',
  'iPhone doesn’t let openGym vibrate. A sound or a flash does the job.': 'Το iPhone δεν αφήνει το openGym να δονηθεί. Ένας ήχος ή μια αναλαμπή κάνουν τη δουλειά.',
  'No account, no cloud. Back it up anytime in Data & backup.': 'Χωρίς λογαριασμό, χωρίς cloud. Δημιούργησε αντίγραφο ασφαλείας όποτε θες στα Δεδομένα και αντίγραφα ασφαλείας.',
  'Effort per set is off. Turn it on in Settings → Workout to keep rating.': 'Η προσπάθεια ανά σετ είναι απενεργοποιημένη. Ενεργοποίησέ την στις Ρυθμίσεις → Προπόνηση για να συνεχίσεις να βαθμολογείς.',
  'Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.': 'Βάλε τον κωδικό που δείχνει η άλλη συσκευή σου στις Ρυθμίσεις → Λογαριασμός → Προσθήκη άλλης συσκευής. Έτσι αυτή η συσκευή παίρνει δικό της passkey.',
  'Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.': 'Άνοιξε τις Ρυθμίσεις → Λογαριασμός → «Σύζευξη της εφαρμογής κινητού» στον ιστότοπο openGym όπου είσαι ήδη συνδεδεμένος και μετά βάλε τη διεύθυνσή του και τον κωδικό που εμφανίζεται εκεί.',
  'Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': 'Άνοιξε τις Ρυθμίσεις → Λογαριασμός → «Σύζευξη της εφαρμογής κινητού» στον ιστότοπο openGym σε ένα πρόγραμμα περιήγησης και βάλε τον νέο κωδικό που εμφανίζεται εκεί. Ό,τι κράτησε αυτό το τηλέφωνο συγχωνεύεται στον λογαριασμό σου.',
