  'Copy this exercise’s warm-up sets, and the rest and note from its Exercise settings, into the routine. A note added for today stays with this workout. Your workout history is kept.': 'Αντίγραψε στη ρουτίνα τα σετ προθέρμανσης αυτής της άσκησης, καθώς και το διάλειμμα και τη σημείωση από τις Ρυθμίσεις άσκησης. Μια σημείωση που προστέθηκε για σήμερα μένει με αυτή την προπόνηση. Το ιστορικό προπόνησής σου διατηρείται.',
