  'That took a little too long. Give it another go.': 'Αυτό άργησε λίγο. Δοκίμασε ξανά.',
  'This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).': 'Αυτός ο διακομιστής δέχεται αλλαγές μόνο από το {0}. Αν άνοιξες το openGym από άλλη διεύθυνση, όποιος διαχειρίζεται τον διακομιστή μπορεί να ορίσει τα ORIGIN και RP_ID ώστε να ταιριάζουν (ο οδηγός self-hosting δείχνει πώς).',
  'That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.': 'Αυτός ο κωδικός δεν δούλεψε. Οι κωδικοί διαρκούν 5 λεπτά και ισχύουν μία φορά, οπότε πάρε έναν καινούριο.',
