  'Another device synced while you were importing, so its changes were kept next to the backup.': 'Μια άλλη συσκευή συγχρονίστηκε όσο έκανες εισαγωγή, οπότε οι αλλαγές της κρατήθηκαν δίπλα στο αντίγραφο ασφαλείας.',
