  'Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Το πλάνο, οι σημειώσεις ή οι κάρτες γυμναστηρίου σου σε αυτή τη συσκευή δημιουργήθηκαν ενώ ήσουν αποσυνδεδεμένος. Πρόσθεσέ τα στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
  '{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.': '{0} ρουτίνα δημιουργήθηκε σε αυτή τη συσκευή ενώ ήσουν αποσυνδεδεμένος. Πρόσθεσέ τη στο προφίλ σου ή κράτα το προφίλ ακριβώς όπως είναι στον διακομιστή.',
