  'Greys show lighter in dark mode, so buttons don’t look switched off.': 'Τα γκρι εμφανίζονται πιο ανοιχτά στη σκούρα λειτουργία, ώστε τα κουμπιά να μη φαίνονται απενεργοποιημένα.',
  'Greys show darker in light mode, so buttons don’t look switched off.': 'Τα γκρι εμφανίζονται πιο σκούρα στη φωτεινή λειτουργία, ώστε τα κουμπιά να μη φαίνονται απενεργοποιημένα.',
  'custom color picker': 'επιλογέας προσαρμοσμένου χρώματος',
