  'Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.': 'Το απλό http:// δεν είναι κρυπτογραφημένο. Κανένα πρόβλημα στο σπιτικό σου δίκτυο, αλλά χρησιμοποίησε https:// αν ο διακομιστής σου είναι προσβάσιμος από το διαδίκτυο.',
  'Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.': 'Δεν ήταν δυνατή η σύνδεση με το {0} μέσω https://. Αν ο διακομιστής σου τρέχει με απλό http (συνηθισμένο στο σπίτι), πληκτρολόγησε http://{0}.',
