  'Choose the measurements you want to track, then log your first check-in.': 'Επίλεξε τις μετρήσεις που θέλεις να παρακολουθείς και μετά καταχώρισε την πρώτη σου καταγραφή.',
  'Keep the logging form focused on the measurements you actually track.': 'Κράτα τη φόρμα καταχώρισης επικεντρωμένη στις μετρήσεις που πραγματικά παρακολουθείς.',
