  'Each set one step lighter than the one before. The weight above is the first set.': 'Κάθε σετ ένα βήμα πιο ελαφρύ από το προηγούμενο. Το βάρος παραπάνω είναι το πρώτο σετ.',
  'Sets open at {0}. The first set goes up when every set reaches its reps, and the rest follow it.': 'Τα σετ ξεκινούν από {0}. Το πρώτο σετ ανεβαίνει όταν κάθε σετ φτάσει τις επαναλήψεις του και τα υπόλοιπα το ακολουθούν.',
  'The first set goes up when every set reaches its reps, and the rest follow it.': 'Το πρώτο σετ ανεβαίνει όταν κάθε σετ φτάσει τις επαναλήψεις του και τα υπόλοιπα το ακολουθούν.',
