  'Only if your server is behind Cloudflare Access: the service token this phone sends with every request to it. Kept in this phone’s secure storage.': 'Μόνο αν ο διακομιστής σου βρίσκεται πίσω από το Cloudflare Access: το διακριτικό υπηρεσίας που στέλνει αυτό το τηλέφωνο με κάθε αίτημα προς αυτόν. Φυλάσσεται στον ασφαλή χώρο αποθήκευσης του τηλεφώνου.',
