  'Weight means': 'Τι σημαίνει το βάρος',
  'The weight of the one you hold. One arm, so it counts once.': 'Το βάρος αυτού που κρατάς. Ένα χέρι, οπότε μετράει μία φορά.',
  'The weight of one, so 20 means 20 in each hand. Volume counts both.': 'Το βάρος του ενός, οπότε 20 σημαίνει 20 σε κάθε χέρι. Ο όγκος μετράει και τα δύο.',
  'Both together, so 40 means two 20s.': 'Και τα δύο μαζί, οπότε 40 σημαίνει δύο των 20.',
  'Counted as you type it, the way it always was.': 'Μετράται όπως το πληκτρολογείς, όπως πάντα.',
  'You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.': 'Ξεπέρασες το ράφι: ο βαρύτερος αλτήρας σου είναι {0} {1}, οπότε το βάρος μένει ίδιο.',
  'Dumbbells': 'Αλτήρες',
  'The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.': 'Τα βάρη που έχεις, ένας αλτήρας το καθένα. Η πρόοδος, τα deload, οι προθερμάνσεις και τα κουμπιά + και − των ασκήσεων με αλτήρες πέφτουν μόνο σε αυτά.',
  'No list yet, so dumbbell lifts step by their increment as usual.': 'Καμία λίστα ακόμα, οπότε οι ασκήσεις με αλτήρες ανεβαίνουν με το βήμα τους όπως συνήθως.',
  'Fill in {0} to {1} {2}, every {3}': 'Συμπλήρωσε από {0} έως {1} {2}, ανά {3}',
  'Clear the list': 'Καθαρισμός λίστας',
  'Any weight. Tap to list the ones you own.': 'Οποιοδήποτε βάρος. Πάτα για να καταχωρίσεις αυτά που έχεις.',
  'F': 'F',
  'Taken to failure': 'Μέχρι την αστοχία',
  'Nothing left in the tank': 'Τίποτα δεν έμεινε στο ντεπόζιτο',
  'Last set to failure': 'Τελευταίο σετ μέχρι την αστοχία',
  'The last set goes until nothing is left, and counts as all-out effort unless you rate it.': 'Το τελευταίο σετ συνεχίζεται μέχρι να μη μείνει τίποτα και μετράει ως μέγιστη προσπάθεια, εκτός αν το βαθμολογήσεις.',
  'Plan the final set as an all-out one.': 'Σχεδίασε το τελευταίο σετ ως μέγιστης προσπάθειας.',
  'Triple progression': 'Τριπλή πρόοδος',
  'Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.': 'Οι επαναλήψεις ανεβαίνουν στο πάνω όριο του εύρους, μετά προστίθεται ένα σετ, μέχρι τα περισσότερα σετ σου. Όταν όλα είναι στο πάνω όριο, το βάρος ανεβαίνει και επιστρέφεις στα πρώτα σου σετ και επαναλήψεις.',
  'Same weight, aim for {0} reps in every set.': 'Ίδιο βάρος, στόχευσε {0} επαναλήψεις σε κάθε σετ.',
  'Same weight, aim for {0} reps on the last set.': 'Ίδιο βάρος, στόχευσε {0} επαναλήψεις στο τελευταίο σετ.',
  '{0} reps in every set! Add a set at {1} reps.': '{0} επαναλήψεις σε κάθε σετ! Πρόσθεσε ένα σετ στις {1} επαναλήψεις.',
  'Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.': 'Πάνω όριο του εύρους σε όλα τα {0} σετ. {1} {2} παραπάνω, πίσω σε {3} σετ των {4}.',
  'Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.': 'Πάνω όριο του εύρους σε όλα τα {0} σετ. {1} {2} λιγότερη βοήθεια, πίσω σε {3} σετ των {4}.',
  'Short of the target, but more reps than before. Same sets and reps again.': 'Λίγο κάτω από τον στόχο, αλλά περισσότερες επαναλήψεις από πριν. Ξανά τα ίδια σετ και επαναλήψεις.',
  'Missed reps last time. Same sets and reps again ({0} of {1} to go).': 'Έχασες επαναλήψεις την προηγούμενη φορά. Ξανά τα ίδια σετ και επαναλήψεις (απομένουν {0} από {1}).',
  'Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.': 'Κολλημένος για {0} συνεδρίες. Κάνε deload στα {1} {2} και ξεκίνα ξανά με {3} σετ των {4}.',
  'Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.': 'Κολλημένος για {0} συνεδρίες. Πίσω στα {1} {2} βοήθειας, ξεκίνα ξανά με {3} σετ των {4}.',
