  'A numbered dot per exercise, filled as you go. Tap one to jump there.': 'Μια αριθμημένη κουκκίδα ανά άσκηση, που γεμίζει όσο προχωράς. Πάτα μία για να πας εκεί.',
  'Fold away': 'Σύμπτυξη',
  'Show the sets': 'Εμφάνιση των σετ',
  'In List and Compact, a finished exercise folds into one line.': 'Στη Λίστα και στη Συμπαγή προβολή, μια ολοκληρωμένη άσκηση συμπτύσσεται σε μία γραμμή.',
