  'Life happens. Leave yourself a note, and the missed-day nudge lets this one go.': 'Συμβαίνουν αυτά. Άφησε στον εαυτό σου μια σημείωση και η υπενθύμιση χαμένης ημέρας θα το προσπεράσει.',
