  'Allowed {0}': 'Επιτρέπεται: {0}',
  'Anything you type to the Coach': 'Ό,τι πληκτρολογείς στον προπονητή',
  'Change your mind anytime under AI data sharing in the Coach menu.': 'Άλλαξε γνώμη όποτε θες στην Κοινοποίηση δεδομένων σε AI, στο μενού του προπονητή.',
  'Nothing allowed yet': 'Δεν έχει επιτραπεί τίποτα ακόμα',
  'Okay, nothing was sent.': 'Εντάξει, δεν στάλθηκε τίποτα.',
  'Send your training to {0}?': 'Να σταλεί η προπόνησή σου στο {0};',
  'The Coach asks before anything leaves.': 'Ο προπονητής ρωτά πριν φύγει οτιδήποτε.',
  'Through your server': 'Μέσω του διακομιστή σου',
  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'Για να απαντήσει, ο προπονητής στέλνει αυτά μέσω του διακομιστή openGym σου στο {0}, μια υπηρεσία AI εκτός openGym που επέλεξε ο διαχειριστής του διακομιστή σου:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'Για να απαντήσει, αυτή η συσκευή στέλνει αυτά απευθείας στο {0}, μια υπηρεσία AI εκτός openGym, με το κλειδί API σου:',
  'Who may see your training': 'Ποιος μπορεί να δει την προπόνησή σου',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'Σε ποιον μπορεί ο προπονητής να στείλει την προπόνησή σου από αυτή τη συσκευή. Ανάκαλεσέ το και ο προπονητής θα ρωτήσει ξανά την επόμενη φορά. Ένα μοντέλο στο δικό σου δίκτυο δεν χρειάζεται ποτέ ερώτηση.',
  'With your API key': 'Με το κλειδί API σου',
  'Withdraw': 'Ανάκληση',
  'Withdrawn. The Coach will ask before it sends anything again.': 'Ανακλήθηκε. Ο προπονητής θα ρωτήσει πριν στείλει ξανά οτιδήποτε.',
  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'Οι απαντήσεις σου στον προπονητή: στόχος, ημέρες, εξοπλισμός, όρια και τραυματισμοί',
  'Your body weight and goal weight': 'Το σωματικό σου βάρος και το βάρος-στόχος',
  'Your data, your call': 'Τα δεδομένα σου, η απόφασή σου',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': 'Το όνομα, το email και η σύνδεσή σου μένουν εκεί που είναι. Τα υπόλοιπα τα χειρίζεται το {0} με τους δικούς του όρους απορρήτου.',
  'Your plan: routines, exercises, sets, reps and schedule': 'Το πλάνο σου: ρουτίνες, ασκήσεις, σετ, επαναλήψεις και πρόγραμμα',
  'Your unit and language': 'Η μονάδα και η γλώσσα σου',
  'Your workouts: weights, reps, times, effort and session notes': 'Οι προπονήσεις σου: βάρη, επαναλήψεις, χρόνοι, προσπάθεια και σημειώσεις συνεδρίας',
  'Delete my account': 'Διαγραφή του λογαριασμού μου',
  'Removes your profile and everything in it from this server.': 'Αφαιρεί το προφίλ σου και ό,τι περιέχει από αυτόν τον διακομιστή.',
  'Delete your account?': 'Να διαγραφεί ο λογαριασμός σου;',
  'Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.': 'Το προφίλ, οι προπονήσεις, το σωματικό βάρος, οι φωτογραφίες και τα βίντεό σου διαγράφονται οριστικά από αυτόν τον διακομιστή. Δεν υπάρχει αναίρεση και ούτε ο διαχειριστής σου μπορεί να τα επαναφέρει.',
  'Want a copy first? Export a backup. You can import it into openGym anytime.': 'Θες πρώτα ένα αντίγραφο; Εξήγαγε ένα αντίγραφο ασφαλείας. Μπορείς να το εισαγάγεις στο openGym όποτε θέλεις.',
  'Type {0} to confirm.': 'Πληκτρολόγησε {0} για επιβεβαίωση.',
  'Account name': 'Όνομα λογαριασμού',
  'Delete forever': 'Διαγραφή οριστικά',
  'That is not your account name.': 'Αυτό δεν είναι το όνομα του λογαριασμού σου.',
  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'Είσαι ο μόνος διαχειριστής εδώ και άλλα προφίλ χρησιμοποιούν ακόμα αυτόν τον διακομιστή. Κάνε πρώτα διαχειριστή κάποιον άλλον.',
  'Couldn’t delete the account. Nothing was removed.': 'Δεν ήταν δυνατή η διαγραφή του λογαριασμού. Δεν αφαιρέθηκε τίποτα.',
  'Your account is gone. Thanks for every rep.': 'Ο λογαριασμός σου διαγράφηκε. Ευχαριστούμε για κάθε επανάληψη.',
  'Confirm it’s you to delete your openGym account': 'Επιβεβαίωσε ότι είσαι εσύ για να διαγράψεις τον λογαριασμό σου στο openGym',
  'Not confirmed on this phone. Nothing was deleted.': 'Δεν επιβεβαιώθηκε σε αυτό το τηλέφωνο. Δεν διαγράφηκε τίποτα.',
  'This phone has no screen lock, so the name you typed is the only check.': 'Αυτό το τηλέφωνο δεν έχει κλείδωμα οθόνης, οπότε το όνομα που πληκτρολόγησες είναι ο μόνος έλεγχος.',
  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'Το τηλέφωνό σου ελέγχει ότι είσαι εσύ (πρόσωπο, δακτυλικό αποτύπωμα ή κωδικός) και μετά ο λογαριασμός διαγράφεται.',
  'Never miss the end of a rest': 'Μην χάσεις ποτέ το τέλος του διαλείμματος',
  'One quick thing': 'Ένα γρήγορο θέμα',
