  'You can change it anytime in your phone’s settings.': 'Μπορείς να το αλλάξεις όποτε θέλεις στις ρυθμίσεις του τηλεφώνου σου.',
  'openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.': 'Το openGym μπορεί να σε ειδοποιεί όταν τελειώνει ένα διάλειμμα, ακόμα κι αν το τηλέφωνο είναι κλειδωμένο στην τσέπη σου.',
  'A good size for this screen.': 'Ένα καλό μέγεθος για αυτήν την οθόνη.',
