  'Sharper animations aren’t available on this device yet. The built-in ones work everywhere.': 'Τα πιο καθαρά animation δεν είναι ακόμα διαθέσιμα σε αυτή τη συσκευή. Τα ενσωματωμένα δουλεύουν παντού.',
  'Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.': 'Τα πιο καθαρά animation κατεβαίνουν μία φορά για κάθε φιγούρα. Μέχρι να έρθουν βλέπεις τα ενσωματωμένα, ώστε να μην μένει ποτέ κενό.',
  'Still only': 'Μόνο η εικόνα',
