  'Make the box smaller': 'Μίκρυνε το πλαίσιο',
  'Photo removed': 'Η φωτογραφία αφαιρέθηκε',
  'A breather after one side, before the other. The full rest comes once both sides are done.': 'Μια ανάσα μετά τη μία πλευρά, πριν από την άλλη. Το πλήρες διάλειμμα έρχεται όταν τελειώσουν και οι δύο πλευρές.',
  'Like the work sets': 'Όπως τα σετ εργασίας',
