  'Rest between warm-ups': 'Διάλειμμα ανάμεσα στις προθερμάνσεις',
  'Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.': 'Οι προθερμάνσεις είναι ελαφριές, οπότε μπορούν να έχουν μικρότερο διάλειμμα ή και καθόλου. Η τελευταία παίρνει πάντα το πλήρες διάλειμμα πριν από το πρώτο σετ εργασίας.',
  'Add photos': 'Πρόσθεσε φωτογραφίες',
  'Each photo goes on the day it was taken.': 'Κάθε φωτογραφία μπαίνει στην ημέρα που τραβήχτηκε.',
  'No progress photos yet. Add one for today or any day before.': 'Δεν υπάρχουν ακόμα φωτογραφίες προόδου. Πρόσθεσε μία για σήμερα ή για οποιαδήποτε προηγούμενη ημέρα.',
  'The photo says it was taken on {0}. Change the day if it was another one.': 'Η φωτογραφία δείχνει ότι τραβήχτηκε στις {0}. Άλλαξε την ημέρα αν ήταν άλλη.',
  'They all go on the day below.': 'Μπαίνουν όλες στην ημέρα παρακάτω.',
  'Which day is this photo from?': 'Από ποια ημέρα είναι αυτή η φωτογραφία;',
  'Your server keeps photos only on days with a workout. An update lets it keep them for any day.': 'Ο διακομιστής σου κρατά φωτογραφίες μόνο τις ημέρες με προπόνηση. Μια ενημέρωση του επιτρέπει να τις κρατά για οποιαδήποτε ημέρα.',
  'Add {0} photo': 'Πρόσθεσε {0} φωτογραφία',
