  '{0} photos added': { one: 'Προστέθηκε {0} φωτογραφία', other: 'Προστέθηκαν {0} φωτογραφίες' },
  '{0} photo knows its day and goes there. The others go on the day below.': 'Η {0} φωτογραφία ξέρει την ημέρα της και πάει εκεί. Οι υπόλοιπες μπαίνουν στην ημέρα παρακάτω.',
  '{0} photos know their day and go there. The others go on the day below.': { one: 'Η {0} φωτογραφία ξέρει την ημέρα της και πάει εκεί. Οι υπόλοιπες μπαίνουν στην ημέρα παρακάτω.', other: 'Οι {0} φωτογραφίες ξέρουν την ημέρα τους και πάνε εκεί. Οι υπόλοιπες μπαίνουν στην ημέρα παρακάτω.' },
  'Every progress photo, lined up by date, for any day. Plus a before/after slider.': 'Όλες οι φωτογραφίες προόδου, στη σειρά ανά ημερομηνία, για οποιαδήποτε ημέρα. Συν ένα slider πριν/μετά.',
  'Add a backup': 'Πρόσθεσε εναλλακτική',
  'Backups': 'Εναλλακτικές',
  'Backups for {0}': 'Εναλλακτικές για {0}',
  'Everything else': 'Όλα τα υπόλοιπα',
