  'In Cards and Focus, Prev and Next hop over a finished exercise.': 'Στα Cards και Focus, τα Προηγούμενο και Επόμενο προσπερνούν μια ολοκληρωμένη άσκηση.',
  'Skip completed exercises': 'Παράλειψη ολοκληρωμένων ασκήσεων',
  'This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.': 'Αυτή η εφαρμογή δεν μπορεί να επιβεβαιώσει με passkey. Φτιάξε τον κωδικό σε έναν browser όπου είσαι συνδεδεμένος σε αυτό το προφίλ ή πρόσθεσε πρώτα εκεί έναν κωδικό πρόσβασης.',
  'Apple Watch': 'Apple Watch',
  'Weight': 'Βάρος',
  'Send workouts to the watch': 'Στείλε προπονήσεις στο ρολόι',
