  'Not allowed': 'Δεν επιτρέπεται',
  'Turn on Apple Health and the watch measures your heart rate for every set.': 'Ενεργοποίησε το Apple Health και το ρολόι μετράει τον καρδιακό σου ρυθμό σε κάθε σετ.',
  'Tap the wrist when a rest is over': 'Δόνηση στον καρπό όταν τελειώνει ένα διάλειμμα',
