  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'Δεν επιτρέπεται στο ρολόι. Επίτρεψέ το στην εφαρμογή Υγεία στο iPhone σου.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Καρδιακός ρυθμός κατά την προπόνηση και δίπλα σε κάθε σετ, και η προπόνηση αποθηκεύεται στο Apple Health. Το ρολόι ρωτά μία φορά.',
