  'Stop writing to Apple Health?': 'Να σταματήσει η εγγραφή στο Apple Health;',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': 'Ό,τι έχει ήδη γράψει το openGym μπορεί να μείνει στο Apple Health ως δεδομένα σου ή να αφαιρεθεί από εκεί.',
  'Your workouts in Apple Health': 'Οι προπονήσεις σου στο Apple Health',
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': 'Το openGym μπορεί να αποθηκεύει κάθε προπόνηση και ζύγιση στο Apple Health, και το Apple Watch σου μπορεί να δείχνει τον καρδιακό ρυθμό σου όσο σηκώνεις βάρη.',
  'Workouts and weigh-ins saved to Apple Health': 'Προπονήσεις και ζυγίσεις αποθηκευμένες στο Apple Health',
