  'AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.': 'Φοράς AirPods Pro 3 ή Powerbeats Pro 2; Το iPhone σου μετράει τον καρδιακό ρυθμό σε κάθε σετ, εκτός αν το Apple Watch σου το κάνει ήδη.',
