  'Your bar for this type, set in Your bars.': 'Η μπάρα σου για αυτόν τον τύπο, ορισμένη στις Οι μπάρες σου.',
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'Πόσο ζυγίζουν οι μπάρες στο γυμναστήριό σου. Κάθε άσκηση με αυτή τη μπάρα μετράει τους δίσκους από αυτήν, εκτός αν έχεις δώσει στην άσκηση τη δική της. Τα βάρη που καταχωρίζεις μένουν συνολικά.',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'Οι περισσότερες ασκήσεις της βιβλιοθήκης χρησιμοποιούν την “{0}”, μερικές την “{1}”. Για να έχεις κοντή μπάρα σε όλες πρέπει να ορίσεις και τις δύο.',
