  'This device has {0} workouts that are not in this backup. Replacing deletes them.': 'Αυτή η συσκευή έχει {0} προπονήσεις που δεν υπάρχουν σε αυτό το αντίγραφο ασφαλείας. Η αντικατάσταση τις διαγράφει.',
