  'Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.': 'Η προπόνησή σου σε χαρτί: σύνολα, γραφήματα, νέα ρεκόρ και κάθε σετ. Κορνίζωσέ την, τύπωσέ την ή στείλ’ την στον προπονητή σου.',
