  'Heart rate from your watch': 'Καρδιακός ρυθμός από το ρολόι σου',
  'After a workout, each set gets the heart rate your watch saved. Garmin, Fitbit, Galaxy Watch and friends welcome.': 'Μετά από μια προπόνηση, κάθε σετ παίρνει τον καρδιακό ρυθμό που αποθήκευσε το ρολόι σου. Garmin, Fitbit, Galaxy Watch και λοιπά είναι ευπρόσδεκτα.',
  'Weigh-ins from other apps': 'Ζυγίσεις από άλλες εφαρμογές',
  'Your smart scale’s weigh-ins land here. One you type in yourself always wins.': 'Οι ζυγίσεις από την έξυπνη ζυγαριά σου καταλήγουν εδώ. Αυτή που πληκτρολογείς εσύ υπερισχύει πάντα.',
  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last 30 days. Older workouts stay as they are.': 'Το openGym διαβάζει μόνο όσο είναι ανοιχτό: καρδιακό ρυθμό για προπονήσεις της τελευταίας ημέρας, ζυγίσεις των τελευταίων 30 ημερών. Οι παλιότερες προπονήσεις μένουν όπως είναι.',
  'A nudge when you walk into your gym.': 'Μια υπενθύμιση όταν μπαίνεις στο γυμναστήριό σου.',
