  'Quick arrival check': 'Γρήγορος έλεγχος άφιξης',
  'Near a gym, the phone takes a short GPS look (a few minutes at most) so the nudge comes at the door.': 'Κοντά σε γυμναστήριο, το τηλέφωνο ρίχνει μια σύντομη ματιά στο GPS (λίγα λεπτά το πολύ), ώστε η υπενθύμιση να έρχεται στην πόρτα.',
  'Android can take up to half an hour to notice you walked in. Set openGym’s battery use to Unrestricted and the phone takes a short GPS look when you get near a gym, so the nudge comes at the door.': 'Το Android μπορεί να χρειαστεί μέχρι και μισή ώρα για να καταλάβει ότι μπήκες. Όρισε τη χρήση μπαταρίας του openGym σε Απεριόριστη και το τηλέφωνο ρίχνει μια σύντομη ματιά στο GPS όταν πλησιάζεις σε γυμναστήριο, ώστε η υπενθύμιση να έρχεται στην πόρτα.',
  'Gym spotted': 'Εντοπίστηκε γυμναστήριο',
  'Leave it empty for the default.': 'Άφησέ το κενό για την προεπιλογή.',
  'Location access': 'Πρόσβαση τοποθεσίας',
  'Location isn’t allowed for openGym. You can change that in the phone’s settings.': 'Η τοποθεσία δεν επιτρέπεται για το openGym. Μπορείς να το αλλάξεις στις ρυθμίσεις του τηλεφώνου.',
  'My gym': 'Το γυμναστήριό μου',
