  'Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.': 'Το ρολόι ή η ζυγαριά σου γράφει κι εδώ; Τα Garmin, COROS, Fitbit, Withings, Oura και παρόμοια φτάνουν στο openGym με αυτόν τον τρόπο.',
  'Now in Integrations': 'Τώρα στις Ενσωματώσεις',
