  'Automation': 'Αυτοματισμός',
  'AI & API': 'AI και API',
  'Workouts and weigh-ins out, heart rate and scale readings in.': 'Προπονήσεις και ζυγίσεις προς τα έξω, καρδιακοί παλμοί και μετρήσεις ζυγαριάς προς τα μέσα.',
  'Finished workouts and weigh-ins go to Apple Health.': 'Οι ολοκληρωμένες προπονήσεις και οι ζυγίσεις πηγαίνουν στο Apple Health.',
  'Heart rate from your watch fills in each set.': 'Οι καρδιακοί παλμοί από το ρολόι σου συμπληρώνονται σε κάθε σετ.',
  'Weigh-ins from your smart scale land here.': 'Οι ζυγίσεις από την έξυπνη ζυγαριά σου καταλήγουν εδώ.',
  'Finished workouts and weigh-ins go to Health Connect.': 'Οι ολοκληρωμένες προπονήσεις και οι ζυγίσεις πηγαίνουν στο Health Connect.',
  'Bring your Hevy history over with a Pro API key.': 'Φέρε το ιστορικό σου από το Hevy με ένα κλειδί Pro API.',
  'Workouts, routines and weigh-ins, once.': 'Προπονήσεις, ρουτίνες και ζυγίσεις, μία φορά.',
