  'Import a file': 'Εισαγωγή αρχείου',
  'Strong, FitNotes, Hevy CSV, GymMane or an Apple Health export.': 'Strong, FitNotes, Hevy CSV, GymMane ή εξαγωγή του Apple Health.',
  'Reads the export file of another app, once.': 'Διαβάζει μία φορά το αρχείο εξαγωγής μιας άλλης εφαρμογής.',
  'Exercises are matched to the library, you check the rest.': 'Οι ασκήσεις αντιστοιχίζονται με τη βιβλιοθήκη, τα υπόλοιπα τα ελέγχεις εσύ.',
  'Spreadsheet (CSV)': 'Λογιστικό φύλλο (CSV)',
  'Every set, weigh-in and measurement, for Excel and friends.': 'Κάθε σετ, ζύγιση και μέτρηση, για το Excel και παρόμοια.',
  'One row per set, plus body weight and measurements.': 'Μία γραμμή ανά σετ, συν σωματικό βάρος και μετρήσεις.',
  'openGym can read it back in later.': 'Το openGym μπορεί να το διαβάσει ξανά αργότερα.',
  'Tell Home Assistant, n8n or ntfy when you finish a workout.': 'Ενημέρωσε το Home Assistant, το n8n ή το ntfy όταν τελειώνεις μια προπόνηση.',
  'A signed JSON message when a workout is finished, a record falls or you weigh in.': 'Ένα υπογεγραμμένο μήνυμα JSON όταν τελειώνει μια προπόνηση, σπάει ένα ρεκόρ ή ζυγίζεσαι.',
  'Sent by your server, from whichever device you logged on.': 'Στέλνεται από τον διακομιστή σου, από όποια συσκευή κι αν καταχώρισες.',
  'Plans and reviews from the model you pick.': 'Πλάνα και αναλύσεις από το μοντέλο που διαλέγεις.',
  'Reads your plan and the last weeks of training when you ask.': 'Διαβάζει το πλάνο σου και τις τελευταίες εβδομάδες προπόνησης όταν το ζητάς.',
  'Set up on its own page.': 'Ρυθμίζεται στη δική του σελίδα.',
  'MCP server': 'Διακομιστής MCP',
  'Let Claude Desktop, Cursor and friends read your training log.': 'Άσε το Claude Desktop, το Cursor και παρόμοια να διαβάζουν το ημερολόγιο προπόνησής σου.',
