  'A new routine': 'Μια νέα ρουτίνα',
  'A photo or video': 'Μια φωτογραφία ή βίντεο',
  'Add an exercise first, then it’s worth saving.': 'Πρόσθεσε πρώτα μια άσκηση και μετά αξίζει να την αποθηκεύσεις.',
  'Add exercises': 'Προσθήκη ασκήσεων',
  'Add it to the loop': 'Πρόσθεσέ την στον κύκλο',
  'An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.': 'Το ιστορικό, τα ρεκόρ και η πρόοδος μιας άσκησης υπολογίζονται από τις προπονήσεις σου. Διόρθωσε την προπόνηση και θα ακολουθήσουν.',
  'Back home, practice over. Stats is where the gains pile up. Tap it.': 'Πίσω στην αρχική, η προπόνηση τελείωσε. Τα Στατιστικά είναι εκεί όπου μαζεύονται τα κέρδη. Πάτα το.',
  'Back it all up': 'Αντίγραφο ασφαλείας για όλα',
  'Back to Stats': 'Πίσω στα Στατιστικά',
  'Backups, spreadsheets, other apps and sync': 'Αντίγραφα ασφαλείας, λογιστικά φύλλα, άλλες εφαρμογές και συγχρονισμός',
  'Body part': 'Μέρος του σώματος',
  'Build your first plan': 'Φτιάξε το πρώτο σου πλάνο',
  'Call it what you call it. Other names you add help the search find it.': 'Ονόμασέ την όπως τη λες εσύ. Άλλα ονόματα που προσθέτεις βοηθούν την αναζήτηση να τη βρει.',
  'Change them any time in Plan. Past workouts keep what you actually did.': 'Άλλαξέ τες όποτε θέλεις στο Πλάνο. Οι παλιές προπονήσεις κρατούν ό,τι έκανες πραγματικά.',
  'Create it': 'Δημιούργησέ την',
  'Custom exercises live with the rest. Tap Exercises.': 'Οι προσαρμοσμένες ασκήσεις μένουν μαζί με τις υπόλοιπες. Πάτα Ασκήσεις.',
  'Date & time': 'Ημερομηνία και ώρα',
  'Edit a workout': 'Επεξεργασία προπόνησης',
  'Edit your data': 'Επεξεργασία των δεδομένων σου',
  'Every exercise is one tap away. Tap Exercises.': 'Κάθε άσκηση απέχει ένα πάτημα. Πάτα Ασκήσεις.',
  'Every weigh-in': 'Κάθε ζύγιση',
