  'As in Settings': 'Όπως στις Ρυθμίσεις',
  'Get ready: {0}': 'Ετοιμάσου: {0}',
  'Go! {0}': 'Πάμε! {0}',
  'Hold done: {0}': 'Κράτημα ολοκληρώθηκε: {0}',
  'Auto holds off for this workout': 'Το αυτόματο περιμένει για αυτή την προπόνηση',
  'Timed holds start by themselves': 'Τα χρονομετρημένα κρατήματα ξεκινούν μόνα τους',
  'Waiting till you close that': 'Περιμένει μέχρι να το κλείσεις',
  'Up next: {0}, starts by itself': 'Επόμενο: {0}, ξεκινά μόνο του',
  'When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.': 'Όταν τελειώσει το διάλειμμα: 3, 2, 1 και το κράτημα ξεκινά. Κάνε παύση, επανεκκίνηση ή διακοπή όποτε θέλεις.',
  'Holds start by themselves': 'Τα κρατήματα ξεκινούν μόνα τους',
  'Add {0}?': 'Προσθήκη του {0};',
  'Any blank NTAG sticker works. Writing replaces what was on it.': 'Κάθε κενό αυτοκόλλητο NTAG δουλεύει. Η εγγραφή αντικαθιστά ό,τι υπήρχε πάνω του.',
  'Hold the back of your phone to the sticker.': 'Κράτα το πίσω μέρος του κινητού σου στο αυτοκόλλητο.',
  'Hold the top of your iPhone near the sticker.': 'Κράτα το πάνω μέρος του iPhone σου κοντά στο αυτοκόλλητο.',
  'It isn’t in this workout yet.': 'Δεν είναι ακόμα σε αυτή την προπόνηση.',
  'Just check in': 'Απλώς check-in',
  'NFC is off. Turn it on in your phone’s settings and try again.': 'Το NFC είναι απενεργοποιημένο. Ενεργοποίησέ το στις ρυθμίσεις του κινητού σου και δοκίμασε ξανά.',
  'NFC sticker for this exercise': 'Αυτοκόλλητο NFC για αυτή την άσκηση',
  'Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.': 'Βάλ\' το στο ντουλάπι σου, στην τσάντα σου ή στην πόρτα του γυμναστηρίου. Ένα άγγιγμα με το κινητό και μπαίνεις.',
  'Set up an NFC sticker': 'Ρύθμιση αυτοκόλλητου NFC',
  'Shows your gym membership code, ready for the scanner.': 'Εμφανίζει τον κωδικό μέλους του γυμναστηρίου σου, έτοιμο για τον σαρωτή.',
  'Start today’s workout': 'Ξεκίνα τη σημερινή προπόνηση',
  'Starts what’s planned for today, or opens the one already running.': 'Ξεκινά ό,τι έχεις προγραμματίσει για σήμερα ή ανοίγει αυτήν που τρέχει ήδη.',
  'Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.': 'Κόλλα το στο μηχάνημα. Πάτα το κατά τη διάρκεια της προπόνησης για να πας στο {0} ή για να το προσθέσεις.',
  'Sticker ready.': 'Το αυτοκόλλητο είναι έτοιμο.',
  'Sticker ready. Tap it with your phone to try it.': 'Το αυτοκόλλητο είναι έτοιμο. Πάτα το με το κινητό σου για να το δοκιμάσεις.',
  'Tap it at the gym to start your workout or show your code.': 'Πάτα το στο γυμναστήριο για να ξεκινήσεις την προπόνησή σου ή να δείξεις τον κωδικό σου.',
  'That didn’t work. Hold your phone still on the sticker and try again.': 'Δεν δούλεψε. Κράτα το κινητό σου ακίνητο πάνω στο αυτοκόλλητο και δοκίμασε ξανά.',
  'This sticker can’t hold a link. Try an NTAG sticker.': 'Αυτό το αυτοκόλλητο δεν χωράει σύνδεσμο. Δοκίμασε ένα αυτοκόλλητο NTAG.',
  'This sticker is for an exercise you don’t have.': 'Αυτό το αυτοκόλλητο είναι για μια άσκηση που δεν έχεις.',
  'This sticker is locked. Try a blank one.': 'Αυτό το αυτοκόλλητο είναι κλειδωμένο. Δοκίμασε ένα κενό.',
  'This sticker is too small. NTAG213 or bigger works.': 'Αυτό το αυτοκόλλητο είναι πολύ μικρό. Κάνει το NTAG213 ή μεγαλύτερο.',
  'When you tap it': 'Όταν το πατάς',
  'Which code': 'Ποιος κωδικός',
  'Write NFC sticker for this exercise': 'Εγγραφή αυτοκόλλητου NFC για αυτήν την άσκηση',
  'Write sticker': 'Εγγραφή αυτοκόλλητου',
  'openGym isn’t allowed to use NFC here.': 'Το openGym δεν έχει άδεια να χρησιμοποιεί NFC εδώ.',
  '“{0}” added': 'Προστέθηκε το «{0}»',
  'And beside it': 'Και δίπλα του',
  'Best: {0}': 'Καλύτερο: {0}',
  'Every badge collected. Legend.': 'Μάζεψες όλα τα εμβλήματα. Θρύλος.',
  'Freezes full. A missed week uses one, no harm done.': 'Οι παγώσεις είναι γεμάτες. Μια εβδομάδα που χάνεις χρησιμοποιεί μία, κανένα πρόβλημα.',
  'Goal reached': 'Ο στόχος επιτεύχθηκε',
  'Last week: {0}': 'Προηγούμενη εβδομάδα: {0}',
  'Next badge at {0} weeks.': 'Επόμενο έμβλημα στις {0} εβδομάδες.',
  'Next workout': 'Επόμενη προπόνηση',
  'No goal set': 'Χωρίς στόχο',
