  'Week done. The flame lives on.': 'Η εβδομάδα ολοκληρώθηκε. Η φλόγα συνεχίζει να καίει.',
  'Weight goal': 'Στόχος βάρους',
  'What to show': 'Τι θα εμφανίζεται',
  '{0} vs last week': '{0} σε σχέση με την προηγούμενη εβδομάδα',
  '{0} weeks in a row. New badge!': '{0} εβδομάδες στη σειρά. Νέο έμβλημα!',
  '{0} weeks: not yet': '{0} εβδομάδες: όχι ακόμα',
  '{0} weeks: reached': '{0} εβδομάδες: το πέτυχες',
  '{0} PR this month': '{0} PR αυτόν τον μήνα',
  '{0} PRs this month': { one: '{0} PR αυτόν τον μήνα', other: '{0} PR αυτόν τον μήνα' },
  'One more week with a workout earns a freeze.': 'Άλλη μία εβδομάδα με προπόνηση σου δίνει μια πάγωση.',
  '{0} more weeks with a workout earn a freeze.': { one: 'Άλλη {0} εβδομάδα με προπόνηση σου δίνει μια πάγωση.', other: 'Άλλες {0} εβδομάδες με προπόνηση σου δίνουν μια πάγωση.' },
  'Watch on YouTube': 'Δες στο YouTube',
  'Opens a search for good form': 'Ανοίγει αναζήτηση για σωστή τεχνική',
  'Share with a friend': 'Μοιράσου με έναν φίλο',
  'As a routine they can do too': 'Ως ρουτίνα που μπορεί να κάνει κι εκείνος',
  'Nothing to share in this one.': 'Δεν υπάρχει κάτι για κοινοποίηση σε αυτήν.',
  'Link copied. Paste it to a friend.': 'Ο σύνδεσμος αντιγράφηκε. Στείλε τον σε έναν φίλο.',
  'That one’s too big for a link, so it goes as a plan file.': 'Αυτή είναι πολύ μεγάλη για σύνδεσμο, οπότε φεύγει ως αρχείο πλάνου.',
  'Here’s my {0} on openGym 💪': 'Δες το {0} μου στο openGym 💪',
  'Couldn’t make a link for this one.': 'Δεν μπόρεσα να φτιάξω σύνδεσμο για αυτήν.',
  'A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.': 'Ένας σύνδεσμος για το «{0}». Ο φίλος σου τον πατάει και το προσθέτει στο δικό του openGym. Η ρουτίνα ταξιδεύει μέσα στον σύνδεσμο, χωρίς server στη μέση.',
  'Include my weights': 'Να συμπεριληφθούν τα βάρη μου',
  'Off: just sets, reps and rest. They pick their own weights.': 'Κλειστό: μόνο σετ, επαναλήψεις και διάλειμμα. Διαλέγει εκείνος τα δικά του βάρη.',
  'So they know who it’s from.': 'Για να ξέρει από ποιον είναι.',
  'Share link': 'Κοινοποίηση συνδέσμου',
  'From {0}': 'Από {0}',
  'Added as a new routine. Nothing you already have is touched.': 'Προστέθηκε ως νέα ρουτίνα. Τίποτα από όσα έχεις ήδη δεν αλλάζει.',
  'Add to my routines': 'Προσθήκη στις ρουτίνες μου',
  'Added to your routines': 'Προστέθηκε στις ρουτίνες σου',
  'This link is from a newer openGym. Update the app to open it.': 'Αυτός ο σύνδεσμος είναι από νεότερο openGym. Ενημέρωσε την εφαρμογή για να τον ανοίξεις.',
  'This browser can’t open this link. Try it in the openGym app.': 'Αυτό το πρόγραμμα περιήγησης δεν μπορεί να ανοίξει αυτόν τον σύνδεσμο. Δοκίμασέ τον στην εφαρμογή openGym.',
  'Nothing in this routine works here, sorry.': 'Τίποτα από αυτή τη ρουτίνα δεν δουλεύει εδώ, συγγνώμη.',
  'This routine link is broken or cut off.': 'Αυτός ο σύνδεσμος ρουτίνας είναι χαλασμένος ή κομμένος.',
  '(from {0})': '(από {0})',
  'Mostly in the morning. The early bird gets the barbell.': 'Κυρίως το πρωί. Το πρωινό πουλί παίρνει τη μπάρα.',
  'Mostly around lunch. Who needs a lunch break anyway?': 'Κυρίως γύρω στο μεσημέρι. Ποιος χρειάζεται διάλειμμα για φαγητό άλλωστε;',
  'Mostly in the afternoon. The sweet spot.': 'Κυρίως το απόγευμα. Η ιδανική ώρα.',
  'Mostly in the evening. Work, then work out.': 'Κυρίως το βράδυ. Πρώτα δουλειά, μετά προπόνηση.',
  'Mostly late at night. The gym is all yours.': 'Κυρίως αργά το βράδυ. Το γυμναστήριο είναι όλο δικό σου.',
  'Early bird': 'Πρωινό πουλί',
  'Most of your sessions started before 9. The sun was still catching up.': 'Οι περισσότερες προπονήσεις σου ξεκίνησαν πριν τις 9. Ο ήλιος ακόμα προσπαθούσε να σε προλάβει.',
  'Night owl': 'Νυχτοπούλι',
  'Most of your sessions started after 8 pm. The quiet gym is your gym.': 'Οι περισσότερες προπονήσεις σου ξεκίνησαν μετά τις 8 το βράδυ. Το ήσυχο γυμναστήριο είναι δικό σου.',
  'Leg-day loyalist': 'Πιστός στη μέρα των ποδιών',
  'You never skipped leg day. Stairs fear you.': 'Δεν έχασες ποτέ τη μέρα των ποδιών. Τα σκαλιά σε φοβούνται.',
  'Clockwork': 'Ρολόι',
  'Week after week after week. Your calendar knows your name.': 'Εβδομάδα με την εβδομάδα. Το ημερολόγιό σου ξέρει το όνομά σου.',
  'Record breaker': 'Σπάστης ρεκόρ',
