  'Amazfit and other Zepp OS watches talk to openGym through this server. Pair one and your workouts show up on your wrist.': 'Το Amazfit και άλλα ρολόγια Zepp OS επικοινωνούν με το openGym μέσω αυτού του διακομιστή. Σύζευξε ένα και οι προπονήσεις σου εμφανίζονται στον καρπό σου.',
