  'In the Zepp app, open the openGym watch app’s settings and type in this address and code. The code lasts ten minutes.': 'Στην εφαρμογή Zepp, άνοιξε τις ρυθμίσεις της εφαρμογής openGym του ρολογιού και πληκτρολόγησε αυτή τη διεύθυνση και τον κωδικό. Ο κωδικός ισχύει για δέκα λεπτά.',
  'Server address': 'Διεύθυνση διακομιστή',
  'Paired watches': 'Συζευγμένα ρολόγια',
  'Not heard from yet': 'Δεν έχουμε νέα ακόμη',
  'Couldn’t reach your server. Try again in a moment.': 'Δεν ήταν δυνατή η σύνδεση με τον διακομιστή σου. Δοκίμασε ξανά σε λίγο.',
  'F-Droid installs the updates for this build.': 'Το F-Droid εγκαθιστά τις ενημερώσεις για αυτή την έκδοση.',
  'Wear OS watch': 'Ρολόι Wear OS',
  'Not in this build': 'Όχι σε αυτή την έκδοση',
  'Wear OS watches talk to the phone through Google Play services, which F-Droid apps leave out. The APK from opengym.ch and the Google Play app have the watch link.': 'Τα ρολόγια Wear OS επικοινωνούν με το τηλέφωνο μέσω των υπηρεσιών Google Play, τις οποίες οι εφαρμογές του F-Droid δεν περιλαμβάνουν. Το APK από το opengym.ch και η εφαρμογή Google Play έχουν τη σύνδεση με το ρολόι.',
  'Muscles': 'Μύες',
  'Chart': 'Γράφημα',
