  'Average sets a week': 'Μέσος όρος σετ την εβδομάδα',
  'Apple Health or Health Connect, heart rate and recovery tips.': 'Apple Health ή Health Connect, καρδιακός ρυθμός και συμβουλές ανάρρωσης.',
  'Beginner to Elite for your main lifts, measured against your body weight.': 'Από Αρχάριος μέχρι Ελίτ για τις βασικές σου ασκήσεις, σε σχέση με το σωματικό σου βάρος.',
  'Body and health': 'Σώμα και υγεία',
