  'Extras': 'Extra',
  'Film a set and watch it back right under the row.': 'Κινηματογράφησε ένα σετ και δες το ξανά ακριβώς κάτω από τη γραμμή.',
  'Form videos': 'Βίντεο τεχνικής',
  'Halloween, Christmas and the advent calendar. Spooky, festive, optional.': 'Halloween, Χριστούγεννα και το ημερολόγιο έλευσης. Τρομακτικό, γιορτινό, προαιρετικό.',
