  'Log, plan, progress. Nothing else on the screen.': 'Καταχώριση, πλάνο, πρόοδος. Τίποτα άλλο στην οθόνη.',
  'Logging, plans, history, the exercise library and the basic stats are always on.': 'Η καταχώριση, τα πλάνα, το ιστορικό, η βιβλιοθήκη ασκήσεων και τα βασικά στατιστικά είναι πάντα ενεργά.',
