  'Plates and warm-ups': 'Δίσκοι και προθερμάνσεις',
  'Plus weigh-ins, measurements, photos and your health apps.': 'Συν μετρήσεις βάρους, μετρήσεις σώματος, φωτογραφίες και οι εφαρμογές υγείας σου.',
  'Rate each set in RIR or RPE, and see in Stats how hard you really push.': 'Βαθμολόγησε κάθε σετ σε RIR ή RPE και δες στα Στατιστικά πόσο δυνατά πιέζεις πραγματικά.',
  'Reviews your training and suggests changes. You still say yes or no.': 'Εξετάζει την προπόνησή σου και προτείνει αλλαγές. Εσύ λες πάντα ναι ή όχι.',
  'Scheduled Coach reviews take a break while the AI Coach is off. Your setup and chats stay.': 'Οι προγραμματισμένες αναθεωρήσεις του προπονητή κάνουν παύση όσο ο προπονητής AI είναι απενεργοποιημένος. Η ρύθμιση και οι συνομιλίες σου μένουν.',
  'Start from': 'Ξεκίνα από',
  'Streaks, challenges, badges, recaps and your year in openGym.': 'Σερί, προκλήσεις, έμβλημα, ανασκοπήσεις και η χρονιά σου στο openGym.',
  'Streaks, the Coach, themes, the lot.': 'Σερί, ο προπονητής, θέματα, τα πάντα.',
  'Switch off': 'Απενεργοποίηση',
  'Switch off what you don’t use. Nothing gets deleted: switch it back on and it’s all still there.': 'Απενεργοποίησε ό,τι δεν χρησιμοποιείς. Τίποτα δεν διαγράφεται: ενεργοποίησέ το ξανά και είναι όλα εκεί.',
  'Switch off {0}?': 'Απενεργοποίηση του {0};',
  'Switch these off?': 'Απενεργοποίηση αυτών;',
  'The plates to load under every set, and warm-ups that build themselves.': 'Οι δίσκοι που φορτώνεις σε κάθε σετ και προθερμάνσεις που φτιάχνονται μόνες τους.',
  'Training': 'Προπόνηση',
  'Training and body': 'Προπόνηση και σώμα',
  'Watch': 'Ρολόι',
  'Webhooks for Home Assistant and friends, and the MCP server.': 'Webhooks για το Home Assistant και παρόμοια, και ο διακομιστής MCP.',
  'Weigh-ins, measurements, progress photos and your weight goal.': 'Μετρήσεις βάρους, μετρήσεις σώματος, φωτογραφίες προόδου και ο στόχος βάρους σου.',
  'Your membership codes on Home, and NFC stickers that start a workout.': 'Οι κωδικοί μέλους σου στην Αρχική και αυτοκόλλητα NFC που ξεκινούν μια προπόνηση.',
  'Your own mix. Flip the switches below.': 'Δικός σου συνδυασμός. Γύρνα τους διακόπτες παρακάτω.',
