  '{0} stops syncing while Health is off. Nothing is disconnected, and it catches up once Health is back.': 'Το {0} σταματά να συγχρονίζεται όσο η Υγεία είναι απενεργοποιημένη. Τίποτα δεν αποσυνδέεται και ενημερώνεται μόλις επιστρέψει η Υγεία.',
